import{_ as t,o as a,c as s,a6 as n}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse(`{"title":"Impact from a diff","description":"The tests a change affects, read from the tests' history: the tests a changed file defines, those that failed inside it, those that executed it, and with recorded coverage only those that ran the changed lines.","frontmatter":{"title":"Impact from a diff","description":"The tests a change affects, read from the tests' history: the tests a changed file defines, those that failed inside it, those that executed it, and with recorded coverage only those that ran the changed lines.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/change-impact.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/change-impact.html"}],["meta",{"property":"og:title","content":"Impact from a diff | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The tests a change affects, read from the tests' history: the tests a changed file defines, those that failed inside it, those that executed it, and with recorded coverage only those that ran the changed lines."}]]},"headers":[],"relativePath":"features/change-impact.md","filePath":"features/change-impact.md","lastUpdated":1793385926000}`),i={name:"features/change-impact.md"};function o(r,e,h,d,c,l){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="impact-from-a-diff" tabindex="-1">Impact from a diff <a class="header-anchor" href="#impact-from-a-diff" aria-label="Permalink to &quot;Impact from a diff&quot;">​</a></h1><p><code>piwi run impact --base &lt;ref&gt;</code> runs only the tests your change affects. The reporter diffs the working tree against <code>&lt;ref&gt;</code>, and the dashboard maps each changed file to tests through what they were seen to do, never a build-time dependency graph:</p><ul><li><strong>Direct</strong>: a changed file that <em>is</em> a test file maps to the tests defined in it.</li><li><strong>Reach</strong>: a changed support file maps to the tests that failed inside it, per their source frames.</li><li><strong>Code reach</strong>: a changed application file maps to the tests that executed it (<a href="/features/code-reach.html">code reach</a>), and a route handler to the tests that called its route.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> impact</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/main</span></span></code></pre></div><p>It fails safe, widening to the full suite with a warning, when a changed file maps to no test (a stylesheet too, unless <a href="/features/css-coverage.html">CSS coverage</a> maps it) or only through source frames, which miss passing tests. A docs-only change runs nothing. <code>piwi select impact</code> prints the Playwright arguments instead of running them, for a job that passes them to <code>playwright test</code>: nothing when the run widens, and <code>--pass-with-no-tests --grep-invert .</code> when no test is impacted, under which Playwright runs none and passes. <a href="/features/preflight.html"><code>piwi preflight --run</code></a> runs the same tests along with those of the locators the change breaks.</p><h2 id="line-level" tabindex="-1">Line level <a class="header-anchor" href="#line-level" aria-label="Permalink to &quot;Line level&quot;">​</a></h2><p>When tests record coverage (<a href="/features/code-reach.html">code reach</a> at <code>functions</code>, <a href="/features/css-coverage.html">CSS coverage</a>, or <a href="/features/server-coverage.html">server coverage</a>), a modified file selects only the tests that ran the lines you changed, not every test that touched the file. The reporter sends each modified file&#39;s changed lines with the git blob id of its version before the change, and the dashboard reads them against each test&#39;s recorded coverage of that same version:</p><table tabindex="0"><thead><tr><th>A changed line…</th><th>selects the tests that…</th></tr></thead><tbody><tr><td>is a statement, with server coverage at <code>lines</code></td><td>ran that line</td></tr><tr><td>sits inside a function: any other line, an insertion, or coverage at <code>functions</code></td><td>ran that function</td></tr><tr><td>sits inside a style sheet rule, with CSS coverage</td><td>matched that rule</td></tr><tr><td>sits outside every function (module code, a declaration, an attribute), or crosses from one function into the next</td><td>reach the file at all</td></tr></tbody></table><p>An added line counts by the lines around it, so it selects the tests that ran the code it was added to. A test whose coverage cannot rule it out stays in: coverage of another version of the file, coverage with no line or function ranges, or an incomplete capture, or coverage whose run was deleted. A test file, failure frames and route reach are never narrowed. Added, deleted and renamed files count as whole files.</p><p>A changed line inside a function no test ran selects nothing from that file: no test can catch a mistake there. The answer names it as <code>notRun</code>, the line a new test should cover.</p><p>The rule assumes a line a test did not run cannot change that test&#39;s path, as every coverage-based selection does, and it reads each test&#39;s latest recorded coverage. Keep running the full suite on a schedule: it stays the reference.</p><h2 id="read-the-answer" tabindex="-1">Read the answer <a class="header-anchor" href="#read-the-answer" aria-label="Permalink to &quot;Read the answer&quot;">​</a></h2><p><code>piwi select impact --json</code> prints the resolution, and <code>impact.files</code> gives, for each changed file:</p><ul><li><code>level</code>: <code>lines</code> when its tests were read against the changed lines, <code>file</code> when not, <code>none</code> when no test maps to it;</li><li><code>tests</code>, each with how it was selected: <code>test-file</code>, <code>lines</code>, <code>functions</code>, <code>frames</code>, <code>route</code>, or <code>file</code> (its coverage reaches the file and cannot rule it out), and the changed lines it ran;</li><li><code>ruledOut</code>, the tests that reach the file and ran none of its changed lines;</li><li><code>fileLevelLines</code> and <code>notRun</code>, as above.</li></ul><h2 id="for-agents" tabindex="-1">For agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to &quot;For agents&quot;">​</a></h2><p>The <code>get_impacted_tests</code> <a href="/reference/mcp-tools.html#workflow">MCP tool</a> takes a diff (<code>git diff --full-index &lt;base&gt;</code>) and returns the same answer per file, the tests by name, and a command to run them. The <code>run-the-right-tests</code><a href="/features/agent-skills.html">agent skill</a> calls it after every code change, and offers to write a test for the <code>notRun</code> lines.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/test-selection.html">Test selections</a>: saved subsets, shards and the CI guard</li><li><a href="/features/code-reach.html">Code reach</a> and <a href="/features/server-coverage.html">server coverage</a>: what the tests record</li><li><a href="/features/uncovered-changes.html">Uncovered changes</a>: the changed lines no suite ran, on a pull request</li><li><a href="/reference/cli.html#select-run">Piwi CLI</a>: every flag of <code>select</code> and <code>run</code></li></ul>',18)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
